SELECT cal_id, day, title, content, color, address
FROM   calendar    
WHERE  (user_id = #{userId} OR holiday = 1) AND day = #{ id }

SELECT cal_id, day, title, content, color, address
FROM   calendar    
WHERE  cal_id = #{ id }

mapper.update:
UPDATE calendar
SET    title = #{ title }, content = #{ content }, color = #{ color }, address = #{ address }
WHERE  cal_id    = #{ calId }
